-- 025_shift_cycle_templates.sql
-- ── contesto (13/09/2026) ────────────────────────────────────────────────────
-- I cicli dei turni sono ora verificati e stabili (migration 021-024). Per non
-- riscrivere a mano i pattern quando si aggiunge/sposta/sostituisce una persona
-- in una squadra, questo catalogo «memorizza» i cicli pronti: ogni template ha
-- la tipologia di riferimento, opzionalmente la squadra (es. i riposi sfalzati
-- dei Rilievo A/B/C-D sono validi solo lì), il pattern completo e cycle_days.
-- La UI membri offrirà i template della tipologia (prima quelli della squadra),
-- con anteprima dei token e avviso se la lunghezza non combacia col ciclo.
-- Il seed è GENERATO dai pattern attuali in DB (scripts/gen-cycle-templates.mjs,
-- output verificato con la scansione PDF di scripts/verify-scorte-fix.mjs):
-- i template «di squadra» riproducono esattamente i cicli oggi assegnati.
--
-- ── schema ───────────────────────────────────────────────────────────────────
create table if not exists public.shift_cycle_templates (
  id             uuid primary key default gen_random_uuid(),
  shift_type_id  uuid not null references public.shift_types(id) on delete cascade,
  team_id        uuid references public.shift_teams(id) on delete set null,  -- null = valido per tutta la tipologia
  name           text not null,
  description    text,
  pattern        text[] not null,
  cycle_days     int  not null,
  pattern_start  date not null,
  is_builtin     boolean not null default false,  -- true = seed, la UI non permette modifica nome
  created_at     timestamptz not null default timezone('utc', now()),
  unique (shift_type_id, name)
);

create index if not exists shift_cycle_templates_type_idx on public.shift_cycle_templates (shift_type_id);
create index if not exists shift_cycle_templates_team_idx on public.shift_cycle_templates (team_id);

-- ── RLS (convenzione 019) ────────────────────────────────────────────────────
alter table public.shift_cycle_templates enable row level security;

create policy "shift_cycle_templates_select" on public.shift_cycle_templates
  for select to authenticated using (true);
create policy "shift_cycle_templates_insert" on public.shift_cycle_templates
  for insert with check (
    auth.uid() = 'fdd6c008-7a22-42d5-a75b-c44d9edfef12'::uuid
    or exists (select 1 from public.users where id = auth.uid() and is_manager = true)
  );
create policy "shift_cycle_templates_update" on public.shift_cycle_templates
  for update using (
    auth.uid() = 'fdd6c008-7a22-42d5-a75b-c44d9edfef12'::uuid
    or exists (select 1 from public.users where id = auth.uid() and is_manager = true)
  );
create policy "shift_cycle_templates_delete" on public.shift_cycle_templates
  for delete using (
    auth.uid() = 'fdd6c008-7a22-42d5-a75b-c44d9edfef12'::uuid
    or exists (select 1 from public.users where id = auth.uid() and is_manager = true)
  );

